void inicializar_fila(FILA* f) { f->inicio = NULL; f->ultimo = NULL; }

     void entrar_fila(FILA* f, int valor) {
       no* novo = (no*) malloc(sizeof(no));
       novo->adj = valor; novo->peso = 0; novo->id = 0; novo->prox = NULL;
       if (f->ultimo == NULL) { f->inicio = novo; }
       else { f->ultimo->prox = novo; }
       f->ultimo = novo; }

     int sair_fila(FILA* f) {
       if (f->inicio == NULL) return -1;
       no* p = f->inicio; int valor = p->adj;
       f->inicio = p->prox;
       if (f->inicio == NULL) f->ultimo = NULL;
       free(p); return valor; }

